def find_big_and_noise(gi, bg):
    sel={(r,c) for r in range(len(gi)) for c in range(len(gi[0])) if gi[r][c]!=bg}
    seen=set(); outs=[]
    for r,c in sel:
        if (r,c) in seen: continue
        q=deque([(r,c)]); comp=[(r,c)]; seen.add((r,c))
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<len(gi) and 0<=nc<len(gi[0]) and (nr,nc) in sel and (nr,nc) not in seen:
                    seen.add((nr,nc)); comp.append((nr,nc)); q.append((nr,nc))
        outs.append(comp)
    outs.sort(key=len)
    big, noise = outs[-1], outs[0]
    return big, noise

